mapper.select:
SELECT inv.materialid AS materialId, m.sku AS sku, m.name AS materialName, inv.warehouseid AS warehouseId, w.name AS warehouseName, inv.status AS status, COALESCE(SUM(inv.quantity), 0) AS quantity, COALESCE(inv.current_amount, 0) AS currentAmount, COALESCE(inv.unit_cost, 0) AS unitCost FROM t_erp_inventory inv INNER JOIN t_erp_material m ON m.id = inv.materialid AND m.shopid = inv.shopid AND m.isDelete = 0 LEFT JOIN t_erp_warehouse w ON w.id = inv.warehouseid WHERE inv.shopid = #{shopid} AND inv.status = 'fulfillable'
AND inv.warehouseid = #{warehouseid}
AND inv.materialid = #{materialid}
AND m.sku LIKE CONCAT('%', #{sku}, '%')
AND m.name LIKE CONCAT('%', #{name}, '%')
GROUP BY inv.materialid, inv.warehouseid, inv.status HAVING quantity > 0 ORDER BY m.sku, w.name

SELECT rec.id AS recordId, rec.materialid AS materialId, m.sku AS sku, m.name AS materialName, rec.warehouseid AS warehouseId, w.name AS warehouseName, rec.formid AS formId, rec.formtype AS formType, ft.name AS formTypeName, rec.operate AS operate, rec.quantity AS quantity, COALESCE(rec.amount_change, 0) AS amountChange, COALESCE(rec.unit_cost, 0) AS unitCost, rec.voucher_id AS voucherId, rec.invqty AS invQtyAfter, rec.number AS number, rec.opttime AS operateTime FROM t_erp_inventory_record rec INNER JOIN t_erp_material m ON m.id = rec.materialid AND m.shopid = rec.shopid AND m.isDelete = 0 LEFT JOIN t_erp_warehouse w ON w.id = rec.warehouseid LEFT JOIN t_erp_formtype ft ON ft.id = rec.formtype WHERE rec.shopid = #{shopid} AND rec.operate IN ('in', 'out')
AND rec.warehouseid = #{warehouseid}
AND rec.materialid = #{materialid}
AND rec.formtype = #{formtype}
AND rec.opttime >= #{startDate}
AND rec.opttime <= #{endDate}
ORDER BY rec.opttime ASC

SELECT rec.materialid AS materialId, m.sku AS sku, m.name AS materialName, rec.warehouseid AS warehouseId, w.name AS warehouseName, COALESCE(SUM(CASE WHEN rec.operate = 'in' THEN rec.amount_change ELSE 0 END), 0) AS totalInAmount, COALESCE(SUM(CASE WHEN rec.operate = 'out' THEN rec.amount_change ELSE 0 END), 0) AS totalOutAmount, COALESCE(SUM(CASE WHEN rec.operate = 'in' THEN rec.amount_change ELSE -rec.amount_change END), 0) AS netAmount, COALESCE(SUM(CASE WHEN rec.voucher_id IS NOT NULL THEN rec.amount_change ELSE 0 END), 0) AS voucherAmount, COUNT(CASE WHEN rec.voucher_id IS NULL THEN 1 END) AS unVoucherCount, COUNT(CASE WHEN rec.voucher_id IS NOT NULL THEN 1 END) AS voucherCount FROM t_erp_inventory_record rec INNER JOIN t_erp_material m ON m.id = rec.materialid AND m.shopid = rec.shopid AND m.isDelete = 0 LEFT JOIN t_erp_warehouse w ON w.id = rec.warehouseid WHERE rec.shopid = #{shopid} AND rec.operate IN ('in', 'out')
AND rec.warehouseid = #{warehouseid}
AND rec.opttime >= #{startDate}
AND rec.opttime <= #{endDate}
GROUP BY rec.materialid, rec.warehouseid ORDER BY m.sku

SELECT
    DATE(rec.opttime) AS date,
    COALESCE(SUM(CASE WHEN rec.operate = 'in' THEN rec.amount_change ELSE 0 END), 0) AS inAmount,
    COALESCE(SUM(CASE WHEN rec.operate = 'out' THEN rec.amount_change ELSE 0 END), 0) AS outAmount,
    COALESCE(SUM(CASE WHEN rec.operate = 'in' THEN rec.amount_change ELSE -rec.amount_change END), 0) AS netChange,
    SUM(rec.quantity) AS totalQuantity
FROM t_erp_inventory_record rec
WHERE rec.shopid = #{shopid}
  AND rec.operate IN ('in', 'out')

    AND rec.warehouseid = #{warehouseid}


    AND rec.materialid = #{materialid}


    AND rec.opttime >= #{startDate}


    AND rec.opttime <= #{endDate}

GROUP BY DATE(rec.opttime)
ORDER BY date ASC

mapper.update:
UPDATE t_erp_inventory
SET current_amount = #{currentAmount},
    unit_cost = #{unitCost}
WHERE shopid = #{shopid}
  AND materialid = #{materialid}
  AND warehouseid = #{warehouseid}
  AND status = #{status}

UPDATE t_erp_inventory_record
SET amount_change = #{amountChange},
    unit_cost = #{unitCost},
    voucher_id = #{voucherId}
WHERE id = #{id}

mapper.select:
SELECT
    rec.id AS id,
    rec.operate AS operate,
    rec.quantity AS quantity,
    rec.status AS status,
    rec.opttime AS operateTime
FROM t_erp_inventory_record rec
WHERE rec.shopid = #{shopid}
  AND rec.materialid = #{materialid}
  AND rec.warehouseid = #{warehouseid}
  AND rec.operate IN ('in', 'out')

    AND rec.opttime >= #{startDate}

ORDER BY rec.opttime ASC, rec.id ASC

SELECT
    inv.quantity AS quantity,
    COALESCE(inv.current_amount, 0) AS currentAmount,
    COALESCE(inv.unit_cost, 0) AS unitCost
FROM t_erp_inventory inv
WHERE inv.shopid = #{shopid}
  AND inv.materialid = #{materialid}
  AND inv.warehouseid = #{warehouseid}
  AND inv.status = #{status}

SELECT rec.id AS recordId, m.sku AS sku, m.name AS materialName, w.name AS warehouseName, ft.name AS formTypeName, CASE rec.operate WHEN 'in' THEN '入库' WHEN 'out' THEN '出库' ELSE rec.operate END AS operateName, rec.quantity AS quantity, COALESCE(rec.unit_cost, 0) AS unitCost, COALESCE(rec.amount_change, 0) AS amountChange, rec.number AS number, rec.opttime AS operateTime FROM t_erp_inventory_record rec INNER JOIN t_erp_material m ON m.id = rec.materialid AND m.shopid = rec.shopid AND m.isDelete = 0 LEFT JOIN t_erp_warehouse w ON w.id = rec.warehouseid LEFT JOIN t_erp_formtype ft ON ft.id = rec.formtype WHERE rec.shopid = #{shopid} AND rec.operate IN ('in', 'out')
AND rec.warehouseid = #{warehouseid}
AND rec.materialid = #{materialid}
AND rec.opttime >= #{startDate}
AND rec.opttime <= #{endDate}
ORDER BY m.sku, rec.opttime ASC
